shared_urls = {}

@app.route('/screenshare', methods=['POST'])
def screenshare():
    url = request.json['url']
    shared_url_key = str(uuid.uuid4())
    shared_urls[shared_url_key] = url
    return jsonify({'link': f'https://example.com/screenshare/{shared_url_key}'})

@app.route('/screenshare/<shared_url_key>')
